package finance.data;
import finance.account.AccountManager;import finance.bank.*;import net.minecraft.nbt.CompoundTag;import org.junit.jupiter.api.*;import java.util.*;import static org.junit.jupiter.api.Assertions.*;
import finance.company.*;import finance.debt.*;
class BankingPersistenceTest {UUID player=UUID.fromString("00000000-0000-0000-0000-000000006101");@BeforeEach void setup(){EconomySavedData.resetRuntimeState();BankingManager.ensureDefaultBanks();AccountManager.deposit(player,10_000);}@AfterEach void end(){EconomySavedData.resetRuntimeState();}
 @Test void bankingLedgerAccountsAndDaysRoundTrip(){CommercialBank bank=BankingManager.banks().values().iterator().next();var d=BankingManager.depositPlayer(player,bank.id(),3_000,1);BankingManager.closeDay(1);CompoundTag saved=new EconomySavedData().save(new CompoundTag());EconomySavedData.load(saved);CommercialBank loaded=BankingManager.bank(bank.id());assertNotNull(loaded);assertTrue(loaded.ledger().balanceSheet().balanced());assertEquals(3_000,BankingManager.account(d.id()).balance());assertEquals(1,BankingManager.lastSnapshotDay());assertEquals(EconomySavedData.currentDataVersion(),saved.getInt("DataVersion"));}
 @Test void oldSaveCreatesSafeDefaultsWithoutCreatingDeposits(){CompoundTag old=new CompoundTag();old.putInt("DataVersion",20);EconomySavedData.load(old);assertEquals(3,BankingManager.banks().size());assertTrue(BankingManager.accounts().isEmpty());}
 @Test void corruptedCustomerSubledgerRejectsOnlyAffectedBank(){CommercialBank bank=BankingManager.banks().values().iterator().next();BankingManager.depositPlayer(player,bank.id(),3_000,1);CompoundTag saved=new EconomySavedData().save(new CompoundTag());saved.getCompound("Banking").getList("Accounts",10).getCompound(0).putLong("Balance",4_000);EconomySavedData.load(saved);assertNull(BankingManager.bank(bank.id()));assertFalse(BankingManager.banks().isEmpty());}
 @Test void commercialLoanLenderSurvivesRestartWhileLegacyDefaultsToCentralBank(){UUID owner=UUID.randomUUID(),companyId=UUID.randomUUID();CompanyManager.registerDirect(new Company(companyId,"PersistBankLoan",CompanyType.RAW_MATERIALS,1_000_000,owner));CommercialBank bank=BankingManager.banks().values().iterator().next();var result=CompanyLoanManager.applyCommercial(owner,companyId,bank.id(),100_000,0,10,3);assertTrue(result.success());CompoundTag saved=new EconomySavedData().save(new CompoundTag());EconomySavedData.load(saved);CompanyLoan loan=CompanyLoanManager.loans().get(result.id());assertNotNull(loan);assertEquals(LoanLenderType.COMMERCIAL_BANK,loan.lenderType());assertEquals(bank.id(),loan.lenderId());}
}
